#!/usr/bin/env python3
"""Bilingual rune reference, illustrated codex text and recipe guide from actual data."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];A=ROOT/'src/main/resources/assets/badspell';D=ROOT/'src/main/resources/data/badspell/recipe'
langs={code:json.loads((A/f'lang/{code}.json').read_text()) for code in ['de_de','en_us']}
def tr(key,de,en):langs['de_de'][key]=de;langs['en_us'][key]=en
def ui(key,de,en):tr('ui.badspell.'+key,de,en)
for key,de,en in [
 ('codex','Kodex','Codex'),('runes','Runenlexikon','Rune reference'),('back','Zurück','Back'),('add','+ Rune','+ Rune'),('properties','Details','Details'),('search','Suche','Search'),('search_hint','Name, Wirkung, Port oder Datentyp …','Name, effect, port or data type …'),('filter_in','Eingang: %s','Input: %s'),('filter_out','Ausgang: %s','Output: %s'),('any','Alle','Any'),('no_inputs','Keine Eingänge','No inputs'),('inputs','Eingänge','Inputs'),('output','Ausgang: %s','Output: %s'),('results','%s Runen · ab %s · Scrollen für mehr','%s runes · from %s · scroll for more'),('add_rune','%s einfügen','Insert %s'),('socket_hint','Eingang klicken: passende Quelle wählen. Rechtsklick: Verbindung lösen.','Click input: choose a compatible source. Right-click: disconnect.'),('try_template','Vorlage anlegen (Schreibpunkte)','Create template (uses writing points)'),('recipes','Rezepte','Recipes'),('recipe_cost','%s FL · %s Sekunden','%s FL · %s seconds'),('station_cell','Feldzelle: liefert FL. Adapter daneben erforderlich.','Field cell: supplies FL. Requires the adjacent adapter.'),('station_adapter','Zelladapter: verbindet die Feldzelle mit der Station.','Cell adapter: connects the field cell to this station.')]:ui(key,de,en)
for key,de,en in [('trigger','Auslöser','Trigger'),('target','Ziel','Target'),('position','Position','Position'),('region','Bereich','Region'),('vector','Vektor','Vector'),('direction','Richtung','Direction'),('effect','Effekt','Effect'),('condition','Bedingung','Condition'),('yes','Wenn wahr','If true'),('no','Sonst','Otherwise'),('a','A','A'),('b','B','B'),('first','Erster Effekt','First effect'),('second','Zweiter Effekt','Second effect'),('source','Quelle','Source'),('start','Start','Start'),('end','Ende','End'),('path','Pfad','Path'),('value','Wert','Value')]:tr('port.badspell.'+key,de,en)
help={
'call':('Ruft eine unveränderliche Kopie einer eigenen Teilformel auf. Benannte Eingaben erscheinen als typisierte Ports; der Ausgang folgt der Rückgabe.','Calls an immutable copy of your subformula. Named inputs appear as typed ports; the output follows its Return.'),
'impulse':('Startet den Zauber beim Wirken. Liefert ein Ereignis, keine Energie. Verbinde es mit Aktivieren und mit Ziel-Runen.','Starts the spell when cast. Returns an event, not energy. Connect it to Activate and target runes.'),
'activate':('Führt den verbundenen Effekt zum Auslöser aus. Muss der Ausgang eines wirkbaren Zaubers sein. Prüft Budget und bezahlt FL/FK vor der Weltaktion.','Executes the connected effect on its trigger. Must be the output of a castable spell. Checks budget and pays FL/FK before changing the world.'),
'self':('Liefert dich als Wesen. Für Heilung direkt anschließen. Für Licht oder Flächen zuerst Wesenposition verwenden. Selbst ist keine Position!','Returns you as an entity. Connect directly to Heal. For light or areas, use Entity position first. Self is not a position!'),
'entity_position':('Wandelt ein Wesen in dessen aktuelle Blockposition um. Beispiel: Selbst → Wesenposition → Kreis → Schild.','Converts an entity to its current block position. Example: Self → Entity position → Circle → Shield.'),
'entity_health':('Liest die Lebenspunkte des verbundenen Wesens aus dem lokalen Serverkontext. 20 Lebenspunkte entsprechen zehn Herzen.','Reads the connected entity’s health from the local server context. 20 health points equal ten hearts.'),
'has_target':('Wahr, wenn ein lebendes Wesen im Fadenkreuz erkannt wurde. Mit Wenn kombinieren, um einen fehlenden Zielzweig sicher zu überspringen.','True when a living entity is detected under the crosshair. Combine with If to safely skip a branch with no target.'),
'target_entity':('Liefert das erste lebende Wesen im Fadenkreuz, höchstens zwölf Blöcke entfernt. Wände blockieren die Erkennung. Ohne Ziel wird der Zauber ohne Kosten abgelehnt.','Returns the first living entity under the crosshair, up to twelve blocks away. Walls block detection. No target rejects the spell without spending energy.'),
'target_entity_id':('Sucht eine konkrete UUID unter den lokal erfassten Wesen. Feldblick zeigt die UUID. Keine Fernsuche oder Chunk-Ladung.','Looks up a UUID among locally observed entities. Field sight displays UUIDs. Does not search remotely or load chunks.'),
'target_position':('Liefert den freien Zielpunkt vor der angesehenen Blockfläche oder am Ende der Blickreichweite. Für Licht und Flächen.','Returns the target point in front of the viewed block face, or at the end of the look range. Use for light and areas.'),
'target_block':('Liefert den angesehenen Block selbst, nicht den Punkt davor. Für Siegel und lokale Maschinenverbindungen.','Returns the viewed block itself, rather than the point in front. Use for seals and local machine links.'),
'position':('Eine feste Position mit Dimension sowie X Y Z. Diese Koordinaten bewegen sich nicht mit dem Spieler.','A fixed position with dimension and X Y Z. These coordinates do not move with the player.'),
'offset':('Verschiebt eine Position um den Vektor. 1000 Vektoreinheiten sind ein Block. Beispiel: (0,1000,0) setzt den Punkt einen Block höher.','Offsets a position by a vector. 1000 vector units equal one block. Example: (0,1000,0) moves the point one block up.'),
'vector':('Richtung und Stärke als X Y Z in Tausendstel-Blöcken. Für Stoß und Versatz. Y ist oben, Z ist Süden.','Direction and magnitude as X Y Z in thousandths of a block. Used by Push and Offset. Y is up; Z is south.'),
'direction':('Liefert deine Blickrichtung als normierten Vektor. Mit Stoß verbunden schiebt sie das Ziel von dir weg.','Returns your look direction as a normalized vector. Connected to Push, it moves the target away from you.'),
'point':('Macht aus einer Position einen Bereich aus genau einer Blockzelle. Allein entsteht noch kein Effekt.','Converts a position to a region containing exactly one block cell. Does not create an effect on its own.'),
'circle':('Ein waagerechter gefüllter Kreis um die Position. Radius in Blöcken. Die Form wird erst durch einen Effekt wirksam.','A filled horizontal circle around the position. Radius is in blocks. Requires an effect to do anything.'),
'sphere':('Eine gefüllte Kugel um die Position, Radius bis sechs Blöcke. Bei Licht müssen alle betroffenen Zellen frei sein.','A filled sphere around the position, radius up to six blocks. For light, all affected cells must be empty.'),
'ray':('Ein gerader Bereich ab Position entlang einer Richtung, bis 16 Blöcke. Benötigt Position UND Vektor.','A straight region from a position along a direction, up to 16 blocks. Requires BOTH position and vector.'),
'path':('Erstellt bis zu 16 gleichmäßige Wegpunkte zwischen Start und Ende. Licht bewegt sich über diese Punkte statt alle dauerhaft zu beleuchten.','Creates up to 16 evenly spaced waypoints between start and end. Light moves along these points instead of lighting them all permanently.'),
'path_start':('Beginnt einen Pfad an einer Position. Mit Pfad erweitern weitere Wegpunkte hinzufügen.','Starts a path at a position. Use Append path to add more waypoints.'),
'path_append':('Hängt eine Position an einen Pfad an. Maximal 16 Wegpunkte; alle müssen in derselben Dimension liegen.','Appends a position to a path. Maximum 16 waypoints, all in the same dimension.'),
'light':('Erzeugt zeitlich begrenztes echtes Blocklicht im Bereich. Stärke 1–8, Dauer in Ticks. Alle Zielzellen müssen Luft sein. 20 Ticks = 1 Sekunde.','Creates temporary real block light in the region. Strength 1–8; duration in ticks. Every target cell must be air. 20 ticks = 1 second.'),
'heat':('Erzeugt ein endliches Wärmefeld. Schädigt zulässige Wesen im Bereich einmal pro Sekunde. Setzt keine Blöcke in Brand.','Creates a finite heat field. Damages permitted entities in the region once per second. Does not set blocks on fire.'),
'cold':('Erzeugt ein endliches Kältefeld. Friert zulässige Wesen ein, verlangsamt sie und löscht ihr Feuer.','Creates a finite cold field. Freezes permitted entities, slows them and extinguishes their fire.'),
'shield':('Erzeugt ein endliches Schutzfeld. Entfernt eintreffende Projektile im Bereich und drängt fremde Wesen zurück.','Creates a finite shield field. Removes incoming projectiles in the region and pushes other entities back.'),
'heal':('Verleiht einem verletzten Wesen Regeneration. Wirkt nicht bei voller Gesundheit, laufender Regeneration oder während der Heilpause. Selbst ist ein gültiges Ziel.','Grants regeneration to an injured entity. Does not work at full health, during regeneration or during the healing cooldown. Self is a valid target.'),
'push':('Bewegt ein zulässiges Wesen mit dem verbundenen Vektor. Stärke vervielfacht den Vektor; zu große Geschwindigkeiten und sehr mächtige Wesen werden abgelehnt.','Moves a permitted entity using the connected vector. Strength multiplies the vector; excessive speeds and very powerful entities are rejected.'),
'see':('Zeigt Name, Gesundheit und UUID eines Wesens. Es entsteht kein Schaden.','Displays an entity’s name, health and UUID. Does not deal damage.'),
'combine':('Bündelt bis zu acht Effekte in einer Aktivierung. Kosten werden addiert und alle Ziele vorab geprüft. Ein abgelehnter Teil verhindert die ganze Ausführung ohne Energiekosten. Nur Kampf-, Licht- und leere Effekte; keine Transfers.','Combines up to eight effects in one activation. Costs are added and all targets checked first. One rejected part prevents the entire cast without energy cost. Supports combat, light and empty effects; not transfers.'),
'if':('Wählt abhängig von einer Wahr/Falsch-Bedingung genau einen Eingang: Wenn wahr oder Sonst. Der andere Zweig wird nicht ausgewertet. Alle drei Eingänge müssen verbunden sein.','Selects exactly one branch using a true/false condition: If true or Otherwise. The other branch is not evaluated. All three inputs must be connected.'),
'equal':('Vergleicht zwei Werte desselben Typs. Gibt Wahr oder Falsch zurück; Wesen werden über ihre UUID verglichen.','Compares two values of the same type. Returns true or false; entities are compared by UUID.'),
'greater':('Gibt Wahr zurück, wenn Zahl A größer ist als Zahl B. Beispiel: 12 > Gesundheit erkennt weniger als sechs Herzen.','Returns true when number A is greater than number B. Example: 12 > Health detects fewer than six hearts.'),
'number':('Eine feste ganze Zahl. Für Vergleiche und Rechenoperationen.','A constant whole number. Used by comparisons and arithmetic.'),
'boolean':('Ein fester Wahr/Falsch-Wert. Für Bedingungen und Logik.','A constant true/false value. Used by conditions and logic.'),
'and':('Wahr, wenn beide Bedingungen wahr sind.','True when both conditions are true.'),
'or':('Wahr, wenn mindestens eine Bedingung wahr ist.','True when at least one condition is true.'),
'not':('Kehrt Wahr und Falsch um.','Reverses true and false.'),
'add':('Addiert Zahl A und Zahl B. Überlauf lehnt den Zauber ab.','Adds number A and number B. Overflow rejects the spell.'),
'subtract':('Zieht Zahl B von Zahl A ab.','Subtracts number B from number A.'),
'multiply':('Multipliziert Zahl A mit Zahl B.','Multiplies number A by number B.'),
'delay':('Verschiebt das Auslöseereignis um die angegebene Tickzahl. Vorher werden keine Effektkosten abgezogen.','Delays the trigger by the given number of ticks. No effect energy is spent before it is due.'),
'interval':('Wiederholt den Zauber alle 20–1200 Ticks. Jede Ausführung wird neu geprüft und bezahlt; zusätzlich ein Sensor-FL pro Sekunde Intervall. Ohne Begrenzen läuft der Auftrag weiter.','Repeats the spell every 20–1200 ticks. Each execution is checked and paid again, plus one sensor FL per second of interval. Without Limit, the job continues.'),
'limit':('Begrenzt ein Ereignis auf 1–64 erfolgreiche Ausführungen. Energiemangel verbraucht keine Ausführung.','Limits an event to 1–64 successful executions. Insufficient energy does not consume an execution.'),
'abort':('Markiert ein Ereignis als abgebrochen. Ein damit verbundener Aktivieren-Ausgang führt nichts aus.','Marks an event as cancelled. An Activate output connected to it does nothing.'),
'none':('Ein absichtlich leerer Effekt, etwa für den Sonst-Zweig. Keine Effektkosten; periodische Sensorprüfung kostet weiterhin FL.','An intentionally empty effect, useful for Otherwise branches. No effect cost; periodic sensing still costs FL.'),
'check':('Reicht einen Effekt unverändert weiter. Die eigentliche Validierung erfolgt vor Aktivieren. Prüfe erzeugt kein boolesches Ergebnis.','Passes an effect through unchanged. Actual validation happens before Activate. Check does not produce a boolean.'),
'return':('Gibt einen Wert aus einer wiederverwendbaren Teilformel zurück. Eine wirkbare Hauptformel braucht weiterhin Aktivieren als Ausgang.','Returns a value from a reusable subformula. A castable main formula still needs Activate as its output.'),
'input':('Benennt einen typisierten Eingang einer Teilformel. Beim Modulaufruf wird daraus ein Port; ohne Aufruf gilt der eingestellte Standardwert.','Names a typed subformula input. It becomes a port when called as a module; outside a call the configured default is used.'),
'sign':('Erzeugt eine stabile Textsignatur aus Position und Frequenz 1–4. Speichert keine Energie und bindet kein Wesen.','Creates a stable text signature from position and frequency 1–4. Does not store energy or bind an entity.'),
'sign_entity':('Erzeugt eine Textsignatur aus Wesen-UUID und Frequenz. Die Signatur allein wirkt keinen Effekt.','Creates a text signature from entity UUID and frequency. The signature alone does not create an effect.'),
'measure':('Liest die verfügbare FL-Ladung der eigenen angesehenen Station. Nur die im Kontext beobachtete Position kann gemessen werden.','Reads available FL charge from your viewed station. Only the position observed in the context can be measured.'),
'bind':('Speichert eine zeitlich begrenzte lokale Verbindung zwischen zwei Positionen, höchstens 16 Blöcke. Transport erfolgt separat über Übertrage.','Stores a temporary local link between two positions, up to 16 blocks. Transport is performed separately using Transfer.'),
'transfer':('Überträgt bis zu 16 Items zwischen zulässigen lokalen Inventaren. Keine Teilübertragung bei vollem Ziel.','Transfers up to 16 items between permitted local inventories. No partial transfer if the destination is full.'),
'transfer_energy':('Überträgt eine begrenzte Menge FL zwischen eigenen lokalen Stationen. Beide Stationen brauchen eine Feldzelle.','Transfers a limited amount of FL between your local stations. Both stations require a field cell.'),
'seal':('Versiegelt einen Block zeitlich begrenzt für seinen Eigentümer oder löst dessen eigenes Siegel. Keine dauerhaften fremden Sperren.','Temporarily seals a block for its owner, or removes the owner’s seal. Cannot create permanent locks on others’ blocks.')}
for key,(de,en) in help.items():tr('help.badspell.'+key,de,en)
for key,de,en in [('light','Helligkeit am angesehenen Punkt (0–15).','Brightness at the observed point (0–15).'),('rain','1 bei Regen am angesehenen Punkt, sonst 0.','1 if raining at the observed point, otherwise 0.'),('sky','1 bei freiem Himmel am angesehenen Punkt, sonst 0.','1 if the observed point can see the sky, otherwise 0.'),('health','Deine Lebenspunkte, nicht die des angesehenen Wesens. Dafür Wesen-Gesundheit verwenden.','Your health, not the viewed entity’s health. Use Entity health for that.'),('focus','Dein aktueller FK-Vorrat.','Your current FK reserve.'),('field','FL-Ladung der eigenen angesehenen Station.','FL charge of your viewed station.'),('stability','Stabilität des aktuellen Geräts oder Runenfeldes.','Stability of the current device or rune field.'),('biome','Deterministischer Zahlenbezeichner des beobachteten Bioms.','Deterministic numeric identifier of the observed biome.')]:tr('help.badspell.environment_'+key,de,en)
new_names={'entity_position':('Wesenposition','Entity position'),'entity_health':('Wesen-Gesundheit','Entity health'),'has_target':('Ziel vorhanden','Target present'),'offset':('Versatz','Offset'),'add':('Addieren','Add'),'subtract':('Subtrahieren','Subtract'),'multiply':('Multiplizieren','Multiply'),'combine':('Effekte bündeln','Combine effects')}
for key,(de,en) in new_names.items():tr('rune.badspell.'+key,de,en)
for key,de,en in [('self_light','Eigenlicht','Self light'),('frost_push','Froststoß','Frost push'),('adaptive_ward','Wachsamer Schutz','Adaptive ward')]:tr('template.badspell.'+key,de,en)
tr('item.badspell.arcane_codex','Arkaner Kodex','Arcane Codex');tr('key.badspell.codex','Arkanen Kodex öffnen','Open Arcane Codex')
errors={'no_target':('Kein Wesen im Ziel. Richte das Fadenkreuz auf eine lebende Kreatur (max. 12 Blöcke).','No entity targeted. Aim at a living creature (up to 12 blocks).'),'target_unavailable':('Das Wesen ist außer Reichweite, verdeckt oder nicht für diesen Zauber freigegeben.','The entity is out of range, obstructed or not permitted for this spell.'),'full_health':('Heilung unnötig: Das Ziel hat volle Gesundheit. Keine Energie verbraucht.','Healing not needed: the target has full health. No energy spent.'),'heal_cooldown':('Das Ziel regeneriert bereits oder braucht noch eine Heilpause.','The target is already regenerating or still on healing cooldown.'),'combine_unsupported':('Bündeln unterstützt diese Effektart noch nicht. Keine Energie verbraucht.','Combine does not support this effect type yet. No energy spent.'),'combine_duplicate':('Derselbe Effekt ist doppelt auf dasselbe Ziel gebündelt.','The same effect is combined twice on the same target.'),'field_limit':('Zu viele aktive Felder. Warte auf das Ende bestehender Felder.','Too many active fields. Wait for existing fields to expire.'),'denied':('Ein Effektziel ist blockiert oder geschützt. Keine Energie verbraucht.','An effect target is blocked or protected. No energy spent.')}
for key,(de,en) in errors.items():tr('message.badspell.cast_'+key,de,en)
tr('message.badspell.rune_failed','Rune %s (%s) konnte nicht ausgewertet werden. Prüfe ihre Eingänge im Kodex. Keine Energie verbraucht.','Rune %s (%s) could not be evaluated. Check its inputs in the Codex. No energy spent.')
chapters={
'start':('Dein erster Zauber','Your first spell','1. Nimm Formelbuch, Handschuh und eine geladene Feldzelle ins Inventar.\n\n2. Öffne das Buch. Lege über Bibliothek eine Licht-Vorlage an oder verwende Lichtfunke.\n\n3. Speichern → An Handschuh. Mit dem Handschuh auf freie Luft vor einem Block zielen und rechtsklicken.\n\nLicht ist nachts deutlicher. FL steckt in Zellen; FK regeneriert sich nach einer Zauberpause. Die Vorlage anlegen verbraucht Schreibpunkte.','1. Carry a formula book, glove and charged field cell.\n\n2. Open the book. Create a Light template in the Library, or use the starter Light spark.\n\n3. Save → To glove. Aim at empty air in front of a block and right-click with the glove.\n\nLight is clearer at night. FL is stored in cells; FK recovers after a casting pause. Creating a template uses writing points.'),
'editor':('Formeln verbinden','Connect formulas','1. Klicke + Rune. Suche nach einer Wirkung, einem Datentyp oder einem Port. Eingangs- und Ausgangsfilter schränken die Treffer ein.\n\n2. Klicke einen offenen Eingang am Knoten. Die Auswahl zeigt nur Runen mit passendem Ausgang; Einfügen verbindet automatisch.\n\n3. Für vorhandene Knoten: Ausgang rechts anklicken, dann passenden Eingang links. Rechtsklick auf den Eingang trennt die Verbindung.\n\n4. Knoten auswählen, Werte links ändern. Mausrad über dem Canvas zoomt; mittlere Maustaste verschiebt. Über Details scrollen, um weitere Parameter zu sehen. ? erklärt die Rune.\n\nAktivieren als Ausgang setzen. Erst speichern, dann exportieren.','1. Click + Rune. Search by effect, data type or port. Input and output filters narrow the results.\n\n2. Click an open node input. The picker shows only compatible outputs; inserting a rune connects it automatically.\n\n3. For existing nodes: click the output on the right, then a matching input on the left. Right-click an input to disconnect.\n\n4. Select a node and edit values on the left. Wheel over canvas zooms; middle mouse pans. Scroll over Details to reveal more parameters. ? explains the rune.\n\nSet Activate as output. Save before exporting.'),
'targets':('Selbst und Ziele','Self and targets','Selbst liefert ein WESEN. Heilung und Stoß erwarten Wesen. Licht, Wärme, Kälte und Schild erwarten einen BEREICH.\n\nFür ein Feld um dich: Selbst → Wesenposition → Kreis → Schild. Danach Schild an Aktivieren anschließen.\n\nFür eine Kreatur: Impuls → Zielwesen. Wesenposition wandelt das Ziel in einen Ort für ein Kältefeld um.\n\nWände blockieren die Zielerkennung. Ein Ziel außerhalb von zwölf Blöcken wird nicht erkannt. Fremde Spieler sind ohne Freigabe geschützt.\n\nHeilung bei voller Gesundheit ist absichtlich wirkungslos und kostenlos. Die Eigenlicht-Vorlage zeigt die Umwandlung praktisch.','Self returns an ENTITY. Heal and Push expect entities. Light, Heat, Cold and Shield expect a REGION.\n\nFor a field around you: Self → Entity position → Circle → Shield. Then connect Shield to Activate.\n\nFor a creature: Impulse → Target entity. Entity position converts the target into a location for a cold field.\n\nWalls block targeting. Targets beyond twelve blocks are not detected. Other players are protected without consent.\n\nHealing at full health intentionally does nothing and costs nothing. The Self light template demonstrates conversion.'),
'combine':('Mehrere Wirkungen','Multiple effects','Froststoß verbindet echte Teilwirkungen:\n\n1. Zielwesen → Wesenposition → Punkt → Kälte.\n\n2. Dasselbe Zielwesen und Blickrichtung → Stoß.\n\n3. Kälte und Stoß → Effekte bündeln → Aktivieren.\n\nZiel vorhanden steuert einen Wenn-Knoten. Ohne Ziel wählt er Leer; der fehlerhafte Zielzweig wird gar nicht ausgewertet.\n\nBündeln addiert Kosten. Beide Wirkungen werden vorab geprüft. Ist eine unzulässig, wird nichts ausgeführt und keine Energie abgezogen. Bis zu acht Teilwirkungen; Transfers dürfen nicht gebündelt werden.','Frost push connects real component effects:\n\n1. Target entity → Entity position → Point → Cold.\n\n2. The same Target entity and Look direction → Push.\n\n3. Cold and Push → Combine effects → Activate.\n\nTarget present controls an If node. With no target it chooses Empty; the invalid target branch is never evaluated.\n\nCombine adds costs. Both effects are checked first. If one is invalid, nothing runs and no energy is spent. Up to eight effects; transfers cannot be combined.'),
'logic':('Bedingte Magie','Conditional magic','Wachsamer Schutz entscheidet nach deiner Gesundheit:\n\nSelbst → Wesen-Gesundheit. Eine Zahl 12 und die Gesundheit gehen in Größer: 12 > Gesundheit.\n\nWahr: Selbst → Heilung. Falsch: Selbst → Wesenposition → Kreis → Schild.\n\nBeide Effekte und die Bedingung gehen in Wenn Effekt; dessen Ausgang in Aktivieren. Nur der gewählte Zweig wird ausgewertet und bezahlt.\n\nModule: Eine eigene Formel mit benannten Eingaben und Rückgabe speichern, dann über die Bibliothek als Modul einsetzen. Der Aufruf enthält eine unveränderliche Kopie.','Adaptive ward chooses based on your health:\n\nSelf → Entity health. A Number 12 and health feed Greater: 12 > Health.\n\nTrue: Self → Heal. False: Self → Entity position → Circle → Shield.\n\nBoth effects and the condition feed If effect; its output feeds Activate. Only the chosen branch is evaluated and paid.\n\nModules: save your own formula with named inputs and a Return, then insert it as a module from the Library. The call stores an immutable copy.'),
'energy':('Energie und Zeit','Energy and time','FL bezahlt Weltwirkungen. Feldzellen enthalten 100/300/600 FL; mehrere Zellen im Inventar werden gemeinsam verwendet. FK ist persönlicher Fokus.\n\n20 Ticks = eine Sekunde. Verzögere verschiebt ein Ereignis. Intervall wiederholt die Formel; Begrenze gibt die Anzahl erfolgreicher Ausführungen an.\n\nJede Wiederholung wird erneut validiert und bezahlt. Bei Energiemangel pausiert sie. Ein begrenzter Auftrag verliert dabei keinen Durchlauf.\n\nUmschalt+Rechtsklick mit dem Handschuh beendet deine geplanten Zauber. Vier Aufträge gleichzeitig sind erlaubt. Sensorintervalle kosten zusätzlich FL.','FL pays for world effects. Field cells hold 100/300/600 FL; multiple inventory cells are used together. FK is personal focus.\n\n20 ticks = one second. Delay shifts an event. Interval repeats the formula; Limit sets the number of successful executions.\n\nEvery repeat is validated and paid again. Insufficient energy pauses it without consuming a limited execution.\n\nShift-right-click with the glove cancels your scheduled spells. Up to four concurrent jobs are allowed. Sensor intervals cost extra FL.'),
'stations':('Stationen bedienen','Use stations','Lege Zutaten in die linke Arbeitszone. Ergebnisse erscheinen rechts. Zelladapter und Feldzelle gehören in die beiden markierten Energieplätze unten in der Mitte.\n\nDas ? einer Station öffnet ihre echten Verarbeitungsrezepte mit Zutatenbildern, FL und Dauer. Im Rezeptführer kannst du oben die Station wechseln.\n\nSchleifer: Kristalle und Staub. Schmelzofen: Barren und Legierungen. Alchemietisch: Lösungen und Essenzen. Presse: Leerplatten. Gravurstation: Formelbuch und Leerplatte einlegen; das Buch bleibt erhalten.\n\nRunenhalter: beschriebene Platte in den oberen Einzelplatz, Energieversorgung unten. Redstone aktiviert. Der Halter unterstützt derzeit nur Punktlicht!','Place ingredients in the left work area. Results appear on the right. The cell adapter and field cell go in the two marked power slots at the bottom center.\n\nA station’s ? opens its actual processing recipes, showing ingredient icons, FL and duration. Switch station at the top of the recipe guide.\n\nGrinder: crystals and dust. Smelter: ingots and alloys. Alchemy table: solutions and essences. Press: blank plates. Engraving station: insert formula book and blank plate; the book is retained.\n\nRune holder: inscribed plate in the upper single slot, power below. Redstone activates it. The holder currently supports point light only!'),
'tools':('Magische Werkzeuge','Magic tools','Handschuh: Umschalt+Mausrad wechselt 4/8/12 Slots. Eine gespeicherte Formel wird aus dem Buch als eigene Kopie exportiert.\n\nMeißel: feste Blockseite öffnen, höchstens 16 Runen platzieren und verbinden. Speichern verbraucht Haltbarkeit; Abbrechen nicht. Beim Entfernen des Blocks geht die Gravur verloren.\n\nResonanzgabel: Rechtsklick in Luft wechselt Diagnose/Aktivierung. Dann auf eine eigene Gravur klicken.\n\nKompass: Umschalt+Rechtsklick bindet einen Ort. Normaler Rechtsklick zeigt Richtung und Signal.\n\nMonokel: im Kopfslot tragen; M wechselt Aus/Normal/Intensiv. Scans kosten FK. G öffnet jederzeit diesen Kodex.','Glove: Shift-wheel cycles 4/8/12 slots. A saved formula is exported from the book as an independent copy.\n\nChisel: open a solid block face, place and connect up to 16 runes. Saving consumes durability; cancelling does not. Removing the block destroys the engraving.\n\nResonance fork: right-click air to switch diagnosis/activation, then click your engraving.\n\nCompass: Shift-right-click binds a location. Normal right-click shows direction and signal.\n\nMonocle: wear in the head slot; M cycles Off/Normal/Intense. Scans cost FK. G opens this Codex anytime.'),
'problems':('Wenn nichts passiert','When nothing happens','Kein Ziel: Stelle dich näher an die Kreatur und ziele auf ihren Körper. Verwende Ziel vorhanden + Wenn für sichere optionale Ziele.\n\nSelbst passt nicht: Ein Wesen ist kein Ort! Wesenposition wandelt es um. Punkt oder Kreis macht daraus einen Bereich.\n\nHeilung: Nur verletzte Ziele ohne laufende Regeneration. Energie wird bei Ablehnung nicht abgezogen.\n\nKein Licht: Alle betroffenen Zellen müssen Luft sein. Eine Kugel, die in den Boden reicht, ist ungültig. Beginne mit Punktlicht.\n\nRote Ports: Typen oder Pflichtverbindungen stimmen nicht. Prüfen zeigt Knoten und Port. Nutze die Suche nach Ein-/Ausgang.\n\nStation steht: Status unten lesen. Adapter, Zellladung, Zutaten und freien Ausgabeplatz prüfen.','No target: move closer and aim at the creature’s body. Use Target present + If for safe optional targeting.\n\nSelf does not fit: an entity is not a location! Entity position converts it. Point or Circle turns it into a region.\n\nHealing: only injured targets without ongoing regeneration. Rejected casts do not spend energy.\n\nNo light: every affected cell must be air. A sphere intersecting the ground is invalid. Start with Point light.\n\nRed ports: types or required connections are wrong. Validate identifies the node and port. Search by input/output.\n\nStation stopped: read the status below. Check adapter, charge, ingredients and output space.')}
